for step in (16,20,24,28,32,36,40,48):
 cc=[]
 for y in range(step//2,1024,step):
  labels=np.where(md[y]<28,lab[y],-1)
  # modal filter in 17px window using per-label majority
  sm=np.empty_like(labels)
  for x in range(1024):
   a=max(0,x-8);b=min(1024,x+9); z=labels[a:b]; z=z[z>=0]
   sm[x]=np.bincount(z,minlength=10).argmax() if len(z)>=9 else -1
  # runs, drop shorter than 12 px, count
  runs=[];last=-99;st=0
  for x,k in enumerate(sm):
   if k!=last:
    if last>=0 and x-st>=12:runs.append((st,x-1,last))
    st=x;last=k
  if last>=0 and 1024-st>=12:runs.append((st,1023,last))
  cc.append(len(runs))
 print('step',step,'rows',len(cc),'run counts',sum(cc),'avg',round(np.mean(cc),1),'max',max(cc))
